const DRV_GUIDE = [["ব্যবহারিক পরীক্ষা (মাঠে গাড়ি চালানো)", "সাধারণত গাড়ি স্টার্ট ও গিয়ার বদল, ব্রেক ও ক্লাচের ব্যবহার, মোড় নেওয়া, রিভার্স বা পার্কিং, ট্রাফিক সংকেত ও ইশারা মানা এবং আত্মবিশ্বাসের সঙ্গে নিরাপদে চালানো দেখা হয়। চালানোর আগে আয়না ও সিটবেল্ট ঠিক করুন, শান্ত থাকুন, তাড়াহুড়া করবেন না।"], ["মৌখিক পরীক্ষা", "নাম-ঠিকানা, অভিজ্ঞতা, লাইসেন্সের ধরন, ট্রাফিক সাইন ও আইন, গাড়ির মৌলিক যন্ত্রাংশ, দুর্ঘটনায় করণীয়, প্রাথমিক চিকিৎসা এবং আচরণ সম্পর্কে প্রশ্ন আসতে পারে। স্পষ্ট ও বিনয়ের সঙ্গে উত্তর দিন; না জানলে অনুমানে ভুল বলার চেয়ে সততার সঙ্গে বলুন।"], ["লিখিত পরীক্ষার প্রস্তুতি", "বাংলা, ইংরেজি, গণিত, সাধারণ জ্ঞান ও টেকনিক্যাল বিষয়ে প্রস্তুতি নিন। বানান, সাধারণ ব্যাকরণ, শতকরা ও কাজ-সময়ের অঙ্ক, বাংলাদেশ ও আন্তর্জাতিক বিষয়, ট্রাফিক নিয়ম এবং ক্লাচ, ব্রেক, ইঞ্জিনের কাজ ভালো করে শিখুন।"], ["আবেদনের কাগজপত্র", "শিক্ষাগত সনদ, বৈধ ড্রাইভিং লাইসেন্স, অভিজ্ঞতার সনদ, জাতীয় পরিচয়পত্র, পাসপোর্ট সাইজ ছবি, নাগরিকত্ব সনদ ও প্রয়োজনীয় ফি। সবসময় আসল বিজ্ঞপ্তি ধরে কাগজপত্র মিলিয়ে নিন।"], ["জরুরি কথা", "এখানে দেওয়া তথ্য সাধারণ ধারণা মাত্র। প্রতিটি নিয়োগের পরীক্ষার ধাপ, বিষয় ও নম্বর বণ্টন আলাদা হয়, তাই আসল নিয়োগ বিজ্ঞপ্তি ভালো করে দেখুন।"]];

